return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ne_NP','project-id-version'=>'babilim-0.1.0-ne_NP-babilim-0.1.0-ne_NP-20261030T031020','pot-creation-date'=>'2026-10-30T06:25:36+00:00','po-revision-date'=>'2026-10-30T06:25:36+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'तपाईंको साइटमा पहिले नै इन्स्टल गरिएका प्लगइन र थिमहरूका लागि हराइरहेका अनुवादहरू थप्छ।','Translations'=>'अनुवादहरू','Babilim Settings'=>'Babilim सेटिङहरू','Settings'=>'सेटिङहरू','You are not allowed to do this.'=>'तपाईंलाई यो गर्न अनुमति छैन।','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'कम्पोनेन्टहरू कम चयन गर्नुहोस्: प्रत्येक रनमा बढीमा %1$d कार्यहरू (तपाईंले %2$d चयन गर्नुभयो)।','That component is not installed on this site, so a translation cannot be requested for it.'=>'त्यो कम्पोनेन्ट यो साइटमा इन्स्टल गरिएको छैन, त्यसैले यसका लागि अनुवादको अनुरोध गर्न सकिँदैन।','Already installed.'=>'पहिले नै इन्स्टल गरिएको छ।','Downloaded and installed.'=>'डाउनलोड र इन्स्टल गरियो।','Babilim has not been enabled for this site yet.'=>'यो साइटको लागि Babilim अझै सक्षम गरिएको छैन।','No build is available to download for this locale.'=>'यो लोकेलका लागि डाउनलोड गर्न सकिने कुनै बिल्ड उपलब्ध छैन।','Rolled back to the previous build.'=>'अघिल्लो बिल्डमा रोलब्याक गरियो।','Rolled back and reported.'=>'रोलब्याक गरियो र रिपोर्ट गरियो।','Rolled back, but the report could not be sent: %s'=>'रोलब्याक गरियो, तर रिपोर्ट पठाउन सकिएन: %s','Removed.'=>'हटाइयो।','Translation requested.'=>'अनुवादको अनुरोध गरियो।','This component was already uploaded. Babilim is checking it now.'=>'यो कम्पोनेन्ट पहिले नै अपलोड गरिएको थियो। Babilim ले अहिले यसको जाँच गर्दैछ।','Upload cancelled.'=>'अपलोड रद्द गरियो।','Upload complete — translation requested.'=>'अपलोड सम्पन्न — अनुवादको अनुरोध गरियो।','This component does not declare a version number, so a translation cannot be requested for it.'=>'यो कम्पोनेन्टले संस्करण नम्बर घोषणा गरेको छैन, त्यसैले यसका लागि अनुवादको अनुरोध गर्न सकिँदैन।','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'यो कम्पोनेन्टको संस्करण नम्बर %d अक्षरभन्दा लामो छ, जुन Babilim ले सम्हाल्न सक्दैन, त्यसैले यसका लागि अनुवादको अनुरोध गर्न सकिँदैन।','A translation cannot be requested for that locale on this site right now.'=>'यो साइटमा अहिले त्यो लोकेलका लागि अनुवादको अनुरोध गर्न सकिँदैन।','Thank you. Your report was sent.'=>'धन्यवाद। तपाईंको रिपोर्ट पठाइयो।','This report does not name a valid plugin or theme and locale.'=>'यो रिपोर्टले मान्य प्लगइन वा थिम र लोकेल उल्लेख गरेको छैन।','Please choose a category for this report.'=>'कृपया यो रिपोर्टको लागि वर्ग छान्नुहोस्।','This report is missing a valid build to report against.'=>'यो रिपोर्टमा रिपोर्ट गर्न मिल्ने मान्य बिल्ड छैन।','This build is not one this site currently knows about for this component/locale.'=>'यो बिल्ड यस साइटले यो कम्पोनेन्ट/लोकेलका लागि हाल चिनेको बिल्ड होइन।','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" फिल्ड धेरै लामो छ: यसमा %2$d अक्षर छन् र सीमा %3$d हो। केही पठाइएन; कृपया यसलाई छोटो बनाएर फेरि प्रयास गर्नुहोस्।','Original string'=>'मूल स्ट्रिङ','String context'=>'स्ट्रिङको सन्दर्भ','Current translation'=>'हालको अनुवाद','Suggested translation'=>'सुझाव गरिएको अनुवाद','Note (optional)'=>'टिप्पणी (ऐच्छिक)','Where you saw this (optional)'=>'तपाईंले यो कहाँ देख्नुभयो (ऐच्छिक)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'सेवाद्वारा Babilim सिंक अस्थायी रूपमा ढिलो गरिएको छ (दर सीमित); यसले %s पछि फेरि प्रयास गर्नेछ।','The locale you added is not valid: use a WordPress locale code such as ll_CC (letters, digits, underscore, hyphen or @, at most %d characters). Nothing was saved.'=>'तपाईंले थप्नुभएको लोकेल मान्य छैन: ll_CC जस्तो WordPress लोकेल कोड प्रयोग गर्नुहोस् (अक्षर, अङ्क, अन्डरस्कोर, हाइफन वा @, बढीमा %d अक्षर)। केही सुरक्षित गरिएन।','Settings saved.'=>'सेटिङहरू सुरक्षित गरियो।','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'यो खुला भएमा, अनइन्स्टल गर्दा यो साइटको पहिचान पनि मेटिन्छ। त्यसपछि यो साइटमा जोडिएको सशुल्क इजाजतपत्र स्वतः पुनःप्राप्त गर्न सकिँदैन; यसलाई फिर्ता पाउन तपाईंले %s मा Babilim सहयोगसँग सम्पर्क गर्नुपर्नेछ।','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'प्लगइन मेटाउँदा यो साइटको पहिचान मेटाउन Babilim सेट गरिएको छ। त्यसपछि यो साइटमा जोडिएको सशुल्क इजाजतपत्र स्वतः पुनःप्राप्त गर्न सकिँदैन; तपाईंले %s मा Babilim सहयोगसँग सम्पर्क गर्नुपर्नेछ। पहिचान राख्न, Cancel थिच्नुहोस्, Babilim सेटिङहरूमा "अनइन्स्टल गर्दा Babilim का सबै डेटा मेटाउनुहोस्" को चिन्ह हटाउनुहोस्, र फेरि निष्क्रिय गर्नुहोस्। जसरी भए पनि निष्क्रिय गर्ने?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'यो नेटवर्कको %1$d साइटलाई प्लगइन मेटाउँदा आफ्नो Babilim पहिचान मेटाउन सेट गरिएको छ। त्यस साइटमा जोडिएको सशुल्क इजाजतपत्र त्यसपछि स्वतः पुनःप्राप्त गर्न सकिँदैन; तपाईंले %2$s मा Babilim सहयोगसँग सम्पर्क गर्नुपर्नेछ। पहिचान राख्न, Cancel थिच्नुहोस्, त्यस साइटको Babilim सेटिङहरूमा "अनइन्स्टल गर्दा Babilim का सबै डेटा मेटाउनुहोस्" को चिन्ह हटाउनुहोस्, र फेरि निष्क्रिय गर्नुहोस्। जसरी भए पनि निष्क्रिय गर्ने?' . "\0" . 'यो नेटवर्कका %1$d साइटहरूलाई प्लगइन मेटाउँदा आफ्नो Babilim पहिचान मेटाउन सेट गरिएको छ। ती साइटहरूमा जोडिएका सशुल्क इजाजतपत्रहरू त्यसपछि स्वतः पुनःप्राप्त गर्न सकिँदैन; तपाईंले %2$s मा Babilim सहयोगसँग सम्पर्क गर्नुपर्नेछ। पहिचानहरू राख्न, Cancel थिच्नुहोस्, प्रत्येक साइटको Babilim सेटिङहरूमा "अनइन्स्टल गर्दा Babilim का सबै डेटा मेटाउनुहोस्" को चिन्ह हटाउनुहोस्, र फेरि निष्क्रिय गर्नुहोस्। जसरी भए पनि निष्क्रिय गर्ने?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'यो नेटवर्कमा साइटहरू एक-एक गरी जाँच गर्न धेरै नै छन्, र तीमध्ये केही प्लगइन मेटाउँदा आफ्नो Babilim पहिचान मेटाउन सेट गरिएका हुन सक्छन्। यस्तो साइटमा जोडिएको सशुल्क इजाजतपत्र स्वचालित रूपमा पुनः प्राप्त गर्न सकिँदैन; तपाईंले %s मा Babilim सहायतामा सम्पर्क गर्नुपर्नेछ। पहिचानहरू जोगाउन, रद्द गर्नुहोस् थिच्नुहोस्, प्रत्येक साइटको Babilim सेटिङहरूमा "अनइन्स्टल गर्दा Babilim का सबै डेटा मेटाउनुहोस्" को चिन्ह हटाउनुहोस्, र फेरि निष्क्रिय गर्नुहोस्। जे भए पनि निष्क्रिय गर्ने?','Open Babilim settings'=>'Babilim सेटिङहरू खोल्नुहोस्','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim ले यो साइट प्रमाणित गर्न सकेन, त्यसैले केही पनि डाउनलोड वा स्थापना गरिएको छैन।','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'सेवाले तपाईंको साइटमा पुग्न सकेन। फायरवाल, सुरक्षा प्लगइन वा होस्टको नियमले अनुरोध रोकिरहेको हुन सक्छ; कृपया /wp-json/babilim/v1/challenge मा अनुरोधहरूलाई अनुमति दिनुहोस्।','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'तपाईंको साइटले जवाफ दिन धेरै समय लियो। कृपया पछि फेरि प्रयास गर्नुहोस्, र तपाईंको होस्ट धेरै ढिलो वा ओभरलोड भएको छैन भनी जाँच गर्नुहोस्।','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'तपाईंको साइटले जवाफ दियो, तर अपेक्षित जवाफ दिएन। REST API लाई अर्को प्लगइनले परिवर्तन गरेको हुन सक्छ, वा त्यो endpoint क्यास गरिएको हुन सक्छ; कृपया /wp-json/babilim/v1/challenge लाई क्यासिङ र रिराइटिङबाट बाहिर राख्नुहोस्।','Please check that your site can be reached from the internet, then try again.'=>'कृपया तपाईंको साइट इन्टरनेटबाट पहुँचयोग्य छ भनी जाँच गर्नुहोस्, अनि फेरि प्रयास गर्नुहोस्।','Re-verify'=>'पुनः प्रमाणित गर्नुहोस्','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'यो साइट एकपटकको सिङ्कमा सेवाले स्वीकार गर्ने आकारभन्दा ठूलो छ, त्यसैले केही वस्तुहरू छुटे: %1$d कम्पोनेन्ट र %2$d लोकेल।','This site is verified.'=>'यो साइट प्रमाणित भएको छ।','Registration restarted.'=>'दर्ता पुनः सुरु गरियो।','Sync complete.'=>'सिङ्क पूरा भयो।','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim ले यो साइट सक्षम गर्दै र जाँच गर्दै छ… यो पृष्ठ रिलोड गर्नुहोस् वा अनुसूचित जाँच सकिने प्रतीक्षा गर्नुहोस्।','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim ले सक्षम गर्ने काम पूरा गर्न सकेन (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'एकै पटकमा एउटा मात्र PHP अनुरोध सेवा गर्ने होस्टले यो चरण पूरा गर्न सक्दैन।','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim सक्षम छ: यो साइट प्रमाणित भएको छ र %d कम्पोनेन्ट भेटियो।' . "\0" . 'Babilim सक्षम छ: यो साइट प्रमाणित भएको छ र %d कम्पोनेन्टहरू भेटिए।','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim निष्क्रिय छ। थप केही पठाइँदैन; पहिले नै स्थापना गरिएका अनुवादहरू काम गरिरहन्छन्।','Supplementary translation index rebuilt.'=>'पूरक अनुवाद सूची पुनर्निर्माण गरियो।','Sweep complete: %d file deleted.'=>'सफाइ स्क्यान पूरा भयो: %d फाइल मेटाइयो।' . "\0" . 'सफाइ स्क्यान पूरा भयो: %d फाइलहरू मेटाइए।','Removed %d installed component.'=>'%d स्थापित कम्पोनेन्ट हटाइयो।' . "\0" . '%d स्थापित कम्पोनेन्टहरू हटाइए।','Automatic installs are now off; turn them on again in the settings if you want them.'=>'स्वचालित स्थापनाहरू अब बन्द छन्; चाहनुभयो भने सेटिङहरूमा फेरि खोल्नुहोस्।','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim ले यो साइटमा तपाईंको भाषाको अनुवाद नभएका प्लगइन र थिमहरू फेला पार्छ र प्रत्येकका लागि एउटा स्थापना गर्छ।','Languages found on this site: %s.'=>'यो साइटमा भेटिएका भाषाहरू: %s।','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'उपलब्ध अनुवादहरू एक क्लिकमा स्थापना गर्न सकिन्छ, र छुटेकाहरू अनुरोध गर्न सकिन्छ। त्यसपछि नयाँ अनुवाद र अपडेटहरू स्वचालित रूपमा स्थापना हुन्छन् (निःशुल्क योजनामा, पहिले नै निःशुल्क स्लट प्रयोग गरिरहेका प्लगइन र थिमहरूका लागि मात्र)।','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'निःशुल्क योजनाले सीमित संख्यामा प्लगइन र थिमहरू समेट्छ; Babilim सक्षम गरेपछि तपाईंको सही कोटा सेटिङहरूमा देखाइन्छ।','What is sent when you enable Babilim'=>'Babilim सक्षम गर्दा के पठाइन्छ','Enabling…'=>'सक्षम गर्दै…','Enable Babilim'=>'Babilim सक्षम गर्नुहोस्','By clicking Enable, you agree to send the information listed above to Babilim.'=>'सक्षम गर्नुहोस् थिचेर, तपाईं माथि सूचीबद्ध जानकारी Babilim लाई पठाउन सहमत हुनुहुन्छ।','Check again now'=>'अहिले फेरि जाँच गर्नुहोस्','Babilim installed %d translation automatically since your last visit.'=>'तपाईंको पछिल्लो भ्रमणदेखि Babilim ले %d अनुवाद स्वचालित रूपमा स्थापना गर्‍यो।' . "\0" . 'तपाईंको पछिल्लो भ्रमणदेखि Babilim ले %d अनुवादहरू स्वचालित रूपमा स्थापना गर्‍यो।','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim ले यो साइट सक्षम गर्दै र जाँच गर्दै छ… (पछिल्लो प्रयास: %s)','Check again'=>'फेरि जाँच गर्नुहोस्','No components synced yet.'=>'अहिलेसम्म कुनै कम्पोनेन्ट सिङ्क गरिएको छैन।','%d succeeded'=>'%d सफल भयो' . "\0" . '%d सफल भए','%d skipped'=>'%d वटा छोडियो' . "\0" . '%d वटा छोडिए','%d failed'=>'%d असफल भयो' . "\0" . '%d असफल भए','%d not yet tried'=>'%d अझै प्रयास गरिएको छैन' . "\0" . '%d अझै प्रयास गरिएका छैनन्','Bulk %s:'=>'सामूहिक %s:','%1$s nothing to do.'=>'%1$s गर्नुपर्ने केही छैन।','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'जारी राख्दै…','Continue next batch (%d left)'=>'अर्को ब्याच जारी राख्नुहोस् (%d बाँकी)','Search components'=>'कम्पोनेन्टहरू खोज्नुहोस्','These are the languages this site uses. You can change them in %s.'=>'यी यो साइटले प्रयोग गर्ने भाषाहरू हुन्। तपाईं यिनलाई %s मा परिवर्तन गर्न सक्नुहुन्छ।','Upload this component?'=>'यो कम्पोनेन्ट अपलोड गर्ने?','There is no upload waiting for confirmation.'=>'पुष्टिको प्रतीक्षामा कुनै अपलोड छैन।','Back'=>'फर्कनुहोस्','To translate this component, Babilim needs its source.'=>'यो कम्पोनेन्ट अनुवाद गर्न Babilim लाई यसको स्रोत चाहिन्छ।','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'%1$s (संस्करण %2$s) को सम्पूर्ण प्लगइन वा थिम डाइरेक्टरी Babilim मा अपलोड गरिनेछ।','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'यदि त्यो डाइरेक्टरीमा कुञ्जी, लग वा ग्राहक डेटा छ भने ती पनि अपलोड हुनेछन्। सेवाले सामान्य संवेदनशील फाइलहरू (कन्फिगरेसन, वातावरण, डाटाबेस डम्प, लग, कुञ्जी) हटाउँछ तर सबै फेला पार्छ भन्ने ग्यारेन्टी दिन सक्दैन।','The upload is kept until you ask Babilim to delete it.'=>'तपाईंले Babilim लाई मेटाउन नभनेसम्म अपलोड राखिन्छ।','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'यो सेवाको होस्टिङ प्रदायकद्वारा भण्डारण गरिन्छ र अनुवाद तयार गर्न AI मोडेलहरूद्वारा प्रशोधन गरिन्छ।','The original text and the translations made from it will be provided to other sites that install the same version.'=>'मूल पाठ र यसबाट बनाइएका अनुवादहरू उही संस्करण स्थापना गर्ने अन्य साइटहरूलाई उपलब्ध गराइनेछ।','By continuing you confirm that you have the right to upload this component.'=>'जारी राखेर तपाईं यो कम्पोनेन्ट अपलोड गर्ने अधिकार भएको पुष्टि गर्नुहुन्छ।','Upload and request'=>'अपलोड गरी अनुरोध गर्नुहोस्','Uploading…'=>'अपलोड गर्दै…','Cancel'=>'रद्द गर्नुहोस्','Uploading'=>'अपलोड गर्दै','There is no upload in progress.'=>'कुनै अपलोड प्रगतिमा छैन।','Uploading part %1$d of %2$d…'=>'%2$d मध्ये भाग %1$d अपलोड गर्दै…','Continue'=>'जारी राख्नुहोस्','Confirm'=>'पुष्टि गर्नुहोस्','Remove'=>'हटाउनुहोस्','Roll back'=>'पूर्वस्थितिमा फर्काउनुहोस्','Nothing to confirm.'=>'पुष्टि गर्न केही छैन।','Choose a language'=>'भाषा छान्नुहोस्','Roll back and report'=>'पूर्वस्थितिमा फर्काएर रिपोर्ट गर्नुहोस्','Report a problem'=>'समस्या रिपोर्ट गर्नुहोस्','Nothing to choose.'=>'छान्न केही छैन।','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s। भाषा छान्नुहोस्।','Supplementary translations'=>'पूरक अनुवादहरू','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'प्रत्येक कम्पोनेन्टको आफ्नै योगदान, प्रत्येक लोकेलको साझा default-डोमेन पूरकमा।','Component'=>'कम्पोनेन्ट','Language'=>'भाषा','Included in index'=>'इन्डेक्समा समावेश गरिएको','Entries'=>'प्रविष्टिहरू','Conflicting keys'=>'विवादित कुञ्जीहरू','Yes'=>'हो','No — component inactive'=>'होइन — कम्पोनेन्ट निष्क्रिय छ','No — installed version differs from the active one'=>'होइन — स्थापना गरिएको संस्करण सक्रिय संस्करणभन्दा फरक छ','No — component removed'=>'होइन — कम्पोनेन्ट हटाइएको छ','No'=>'होइन','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'यो काम नेटवर्क प्रशासकले मात्र गर्न सक्छन्, किनभने यसले यस नेटवर्कका सबै साइटहरूले साझा रूपमा प्रयोग गर्ने अनुवाद फाइलहरू परिवर्तन गर्छ।','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim ले यो साइट प्रमाणित गर्ने काम पूरा गर्न सकेन (सेवाले साइटमा फर्केर सम्पर्क गर्न सकेन)। दर्ता रोकिएको छ।','This site already has an active registration that can no longer be recovered automatically.'=>'यो साइटमा पहिल्यै सक्रिय दर्ता छ जुन अब स्वचालित रूपमा पुनः प्राप्त गर्न सकिँदैन।','Restart registration'=>'दर्ता पुनः सुरु गर्नुहोस्','Babilim settings'=>'Babilim सेटिङहरू','General'=>'सामान्य','Advanced'=>'उन्नत','Languages'=>'भाषाहरू','Automatic installs'=>'स्वचालित स्थापनाहरू','Install available translations automatically'=>'उपलब्ध अनुवादहरू स्वचालित रूपमा स्थापना गर्नुहोस्','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'निःशुल्क योजनामा, तपाईंका निःशुल्क स्लटहरूमध्ये एउटा पहिल्यै प्रयोग गरिसकेका कम्पोनेन्टहरू मात्र स्वचालित रूपमा स्थापना हुन्छन्, त्यसैले कुनै नयाँ स्लट लिइँदैन।','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'यो साइट मल्टिसाइट नेटवर्कको हिस्सा हो, जसले नयाँ अनुवादहरू स्वचालित रूपमा स्थापना गर्दैन। पहिल्यै स्थापना भइसकेका अनुवादहरू भने अझै अपडेट हुन्छन्।','Custom overrides'=>'कस्टम ओभरराइडहरू','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'सबै कुरा सफा गर्दा वा यो प्लगइन अनइन्स्टल गर्दा मेरा आफ्नै अनुवाद ओभरराइडहरू राख्नुहोस्।','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'तपाईंले %s मा राखेका अनुवाद फाइलहरूले सधैं Babilim का फाइलहरूभन्दा प्राथमिकता पाउँछन्। यसलाई अनचेक नगरेसम्म ती राखिन्छन्।','Uninstall'=>'अनइन्स्टल','Delete all Babilim data on uninstall'=>'अनइन्स्टल गर्दा Babilim का सबै डेटा मेटाउनुहोस्','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'पूर्वनिर्धारित रूपमा बन्द: प्लगइन मेटाउँदा यस साइटको पहिचान राखिन्छ, ताकि पुनः स्थापना गर्दा त्यसलाई फेरि प्रयोग गर्न सकियोस्।','Account'=>'खाता','Save changes'=>'परिवर्तनहरू सुरक्षित गर्नुहोस्','Disable Babilim'=>'Babilim अक्षम गर्नुहोस्','Installed translations are kept, but no further checks or downloads will run.'=>'स्थापना गरिएका अनुवादहरू राखिन्छन्, तर थप जाँच वा डाउनलोडहरू चल्ने छैनन्।','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim अक्षम गर्ने? स्थापना गरिएका अनुवादहरू राखिन्छन्, तर थप जाँच वा डाउनलोडहरू चल्ने छैनन्।','This site is not registered with Babilim yet.'=>'यो साइट अहिलेसम्म Babilim मा दर्ता गरिएको छैन।','This site is already licensed. Reload the page.'=>'यो साइटसँग पहिल्यै इजाजतपत्र छ। पृष्ठ पुनः लोड गर्नुहोस्।','Checkout is not available for this site right now.'=>'यो साइटको लागि चेकआउट अहिले उपलब्ध छैन।','Could not start checkout: %s'=>'चेकआउट सुरु गर्न सकिएन: %s','Babilim is not enabled.'=>'Babilim सक्षम गरिएको छैन।','Not registered yet'=>'अहिलेसम्म दर्ता गरिएको छैन','Not verified'=>'प्रमाणित गरिएको छैन','Verified'=>'प्रमाणित भयो','Status'=>'स्थिति','Licensed'=>'इजाजतपत्र प्राप्त','Partner'=>'साझेदार','Free'=>'निःशुल्क','License'=>'इजाजतपत्र','Upgrade this site'=>'यो साइट अपग्रेड गर्नुहोस्','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'यो साइटका लागि एकपटकको खरिद: %1$s %2$s। भविष्यका सबै अनुवाद अपडेटहरू समावेश छन्। भुक्तानी नयाँ ट्याबमा Paddle ले ह्यान्डल गर्छ।','This issues a new restore code and the previous one stops working. Continue?'=>'यसले नयाँ पुनर्स्थापना कोड जारी गर्छ र अघिल्लो कोडले काम गर्न छोड्छ। जारी राख्ने?','Show a new restore code'=>'नयाँ पुनर्स्थापना कोड देखाउनुहोस्','rc_…'=>'rc_…','Restore code'=>'पुनर्स्थापना कोड','Restore purchase'=>'खरिद पुनर्स्थापना गर्नुहोस्','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'यस डोमेनका लागि पहिले इजाजतपत्र खरिद गर्नुभएको थियो? चेकआउटमा प्राप्त पुनर्स्थापना कोड प्रविष्ट गर्नुहोस्।','That does not look like a restore code.'=>'यो पुनर्स्थापना कोड जस्तो देखिँदैन।','This restore code was not recognised for this site.'=>'यो पुनर्स्थापना कोड यस साइटका लागि पहिचान भएन।','Too many attempts. Try again tomorrow.'=>'धेरै प्रयासहरू भए। भोलि फेरि प्रयास गर्नुहोस्।','This site must be verified first.'=>'यो साइट पहिले प्रमाणित गरिनुपर्छ।','Could not restore the purchase: %s'=>'खरिद पुनर्स्थापना गर्न सकिएन: %s','Purchase restored. This site is now licensed.'=>'खरिद पुनर्स्थापना भयो। अब यो साइट इजाजतपत्र प्राप्त छ।','This site has no purchase to show a code for.'=>'यो साइटमा कोड देखाउनका लागि कुनै खरिद छैन।','Could not show a new restore code: %s'=>'नयाँ पुनर्स्थापना कोड देखाउन सकिएन: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'तपाईंको नयाँ पुनर्स्थापना कोड: %s। यसलाई सुरक्षित ठाउँमा राख्नुहोस् — अघिल्लो कोडले अब काम गर्दैन।','What is sent when Babilim checks this site'=>'Babilim ले यो साइट जाँच गर्दा के पठाइन्छ','(detected)'=>'(पत्ता लागेको)','No language is managed yet.'=>'अहिलेसम्म कुनै भाषा व्यवस्थापन गरिएको छैन।','Babilim adds translations for every language checked here.'=>'Babilim ले यहाँ चयन गरिएका हरेक भाषाका लागि अनुवादहरू थप्छ।','Add another language'=>'अर्को भाषा थप्नुहोस्','Choose a language…'=>'भाषा छान्नुहोस्…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'सेवाबाट WordPress.org को पूर्ण स्थानीय भाषा सूची लोड गर्न सकिएन, त्यसैले अहिले अरू कुनै भाषा थप्न सकिँदैन।','Theme'=>'थिम','Plugin'=>'प्लगइन','Free quota'=>'निःशुल्क कोटा','Downloads: %1$d/%2$d (%3$s)'=>'डाउनलोडहरू: %1$d/%2$d (%3$s)','Supplementary translation index'=>'पूरक अनुवाद सूची','Built'=>'निर्मित','Included'=>'समावेश गरिएको','Excluded'=>'बहिष्कृत','Already in WordPress core'=>'WordPress कोरमा पहिल्यै छ','Supplementary translation maintenance'=>'पूरक अनुवाद मर्मतसम्भार','Maintenance status is not available right now.'=>'मर्मतसम्भारको स्थिति अहिले उपलब्ध छैन।','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s मा एउटा सफाइ रोकियो: %2$s। केही पनि मेटिएन।','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'पछिल्लो सफाइ %1$s मा: %2$d नयाँ चिन्ह लगाइयो, %3$d फाइल मेटाइयो, %4$d रेकर्ड हटाइयो।','No cleanup has run yet.'=>'अहिलेसम्म कुनै सफाइ चलेको छैन।','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'%1$s मा अर्को अनुरोधसँग अनुवाद सूचकांक (%2$s) लेखन द्वन्द्व भयो र लागू गरिएन; सबैभन्दा पछिल्लो संस्करण राखियो।','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'%1$s मा अनुवाद सूचकांक (%2$s) लेखन पूरा हुन सकेन र लागू गरिएन (%3$s)।','Maintenance'=>'मर्मतसम्भार','Rebuild index now'=>'सूचकांक अहिले पुनर्निर्माण गर्नुहोस्','Sweep now'=>'अहिले सफाइ स्क्यान गर्नुहोस्','Danger zone'=>'खतरा क्षेत्र','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'यस साइटका सबै प्लगइन र थिमका लागि Babilim ले स्थापना गरेका सबै भाषा फाइलहरू हटाउँछ।','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim ले स्थापना गरेका सबै कुरा हटाउने हो? यसले यस साइटका सबै प्लगइन र थिमका लागि Babilim ले स्थापना गरेका सबै भाषा फाइलहरू मेटाउँछ।','Remove everything Babilim installed'=>'Babilim ले स्थापना गरेका सबै कुरा हटाउनुहोस्','This string is too long to be sent as a report, so no report form is offered for it.'=>'यो स्ट्रिङ रिपोर्टको रूपमा पठाउन धेरै लामो छ, त्यसैले यसका लागि रिपोर्ट फारम उपलब्ध गराइएको छैन।','Category'=>'वर्ग','Choose a category…'=>'वर्ग छान्नुहोस्…','Roll back and send report'=>'पूर्वस्थितिमा फर्काउनुहोस् र रिपोर्ट पठाउनुहोस्','Send report'=>'रिपोर्ट पठाउनुहोस्','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'यस कम्पोनेन्टको केही पाठ यसका लेखकले हार्ड-कोड गरेका छन् र भाषा प्याकबाट अनुवाद गर्न सकिँदैन।','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'थिमसँगै समावेश','Bundled with the plugin'=>'प्लगइनसँगै समावेश','Upload was not accepted'=>'अपलोड स्वीकार गरिएन','Upload expired before it finished'=>'अपलोड सकिनु अघि नै म्याद सकियो','No translation'=>'अनुवाद छैन','Upload in progress — continue or cancel'=>'अपलोड हुँदैछ — जारी राख्नुहोस् वा रद्द गर्नुहोस्','Scheduled, waiting to be processed'=>'अनुसूचित, प्रशोधनको प्रतीक्षामा','Translating…'=>'अनुवाद गरिँदैछ…','Translation failed'=>'अनुवाद असफल भयो','Free quota used'=>'निःशुल्क कोटा प्रयोग भइसक्यो','Needs a paid license'=>'सशुल्क इजाजतपत्र चाहिन्छ','Not supported'=>'समर्थित छैन','Status unknown'=>'स्थिति अज्ञात','translation statusInstalled'=>'स्थापना गरिएको','Update available'=>'अद्यावधिक उपलब्ध छ','Removed after a failed integrity check'=>'अखण्डता जाँच असफल भएपछि हटाइयो','Installed · built for %s, new version scheduled'=>'स्थापना गरिएको · %s का लागि बनाइएको, नयाँ संस्करण अनुसूचित','Installed · built for a different version, new version scheduled'=>'स्थापना गरिएको · फरक संस्करणका लागि बनाइएको, नयाँ संस्करण अनुसूचित','Installed · built for %s, translating the new version…'=>'स्थापना गरिएको · %s का लागि बनाइएको, नयाँ संस्करण अनुवाद गरिँदैछ…','Installed · built for a different version, translating the new version…'=>'स्थापना गरिएको · फरक संस्करणका लागि बनाइएको, नयाँ संस्करण अनुवाद गरिँदैछ…','Installed · built for %1$s, this site has %2$s'=>'स्थापना गरिएको · %1$s का लागि बनाइएको, यस साइटमा %2$s छ','Installed · built for %s'=>'स्थापना गरिएको · %s का लागि बनाइएको','Installed · built for a different version'=>'स्थापना गरिएको · फरक संस्करणका लागि बनाइएको','Installed · built for %s, new version failed'=>'स्थापना गरिएको · %s का लागि बनाइएको, नयाँ संस्करण असफल भयो','Installed · built for a different version, new version failed'=>'स्थापना गरिएको · फरक संस्करणका लागि बनाइएको, नयाँ संस्करण असफल भयो','Installed · built for %s, new version needs a paid license'=>'स्थापना गरिएको · %s का लागि बनाइएको, नयाँ संस्करणलाई सशुल्क इजाजतपत्र चाहिन्छ','Installed · built for a different version, new version needs a paid license'=>'स्थापना गरिएको · फरक संस्करणका लागि बनाइएको, नयाँ संस्करणलाई सशुल्क इजाजतपत्र चाहिन्छ','Installed · built for %s, free quota used'=>'स्थापना गरिएको · %s का लागि बनाइएको, निःशुल्क कोटा सकियो','Installed · built for a different version, free quota used'=>'स्थापना गरिएको · फरक संस्करणका लागि बनाइएको, निःशुल्क कोटा सकियो','translation statusAvailable'=>'उपलब्ध','Installed · %s'=>'स्थापना गरिएको · %s','Available · %s'=>'उपलब्ध · %s','Update'=>'अद्यावधिक गर्नुहोस्','Download'=>'डाउनलोड गर्नुहोस्','Updating…'=>'अद्यावधिक गर्दै…','Downloading…'=>'डाउनलोड गर्दै…','Retry request'=>'अनुरोध पुनः प्रयास गर्नुहोस्','Request newer translation'=>'नयाँ अनुवादको अनुरोध गर्नुहोस्','Request translation'=>'अनुवादको अनुरोध गर्नुहोस्','Requesting…'=>'अनुरोध गर्दै…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'अनुवादको अनुरोध गर्दा तपाईंको निःशुल्क स्लटहरू मध्ये एउटा प्रयोग हुन्छ, यदि यो कम्पोनेन्टले पहिले नै एउटा प्रयोग गरिसकेको छैन भने। असफल अनुवादले स्लट फिर्ता गर्दैन।','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'यदि यो कम्पोनेन्टले अहिलेसम्म तपाईंको निःशुल्क स्लटहरू मध्ये कुनै प्रयोग गरेको छैन भने, अनुवादको अनुरोध गर्दा एउटा प्रयोग हुन्छ। असफल अनुवादले स्लट फिर्ता गर्दैन। जारी राख्ने?','No plugins or themes found.'=>'कुनै प्लगइन वा थिम फेला परेन।','Clear filters'=>'फिल्टरहरू हटाउनुहोस्','No components match these filters. %s'=>'यी फिल्टरहरूसँग मिल्ने कुनै कम्पोनेन्ट छैन। %s','Select all'=>'सबै चयन गर्नुहोस्','All'=>'सबै','Available'=>'उपलब्ध','Updates'=>'अद्यावधिकहरू','Requestable'=>'अनुरोध गर्न मिल्ने','Installed'=>'स्थापना गरिएको','Plugins'=>'प्लगइनहरू','Themes'=>'थिमहरू','All languages'=>'सबै भाषाहरू','%d to install'=>'स्थापना गर्न %d' . "\0" . 'स्थापना गर्न %d','Language:'=>'भाषा:','Bulk actions apply to every matching language of each selected component.'=>'सामूहिक कार्यहरू प्रत्येक चयन गरिएको कम्पोनेन्टका सबै मिल्दो भाषाहरूमा लागू हुन्छन्।','Bulk actions apply only to the selected language of each selected component.'=>'सामूहिक कार्यहरू प्रत्येक चयन गरिएको कम्पोनेन्टको चयन गरिएको भाषामा मात्र लागू हुन्छन्।','Version %s'=>'संस्करण %s','Theme · %s'=>'थिम · %s','Plugin · %s'=>'प्लगइन · %s','Remove the %2$s translation of %1$s from this site?'=>'यस साइटबाट %1$s को %2$s भाषाको अनुवाद हटाउने?','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s को %2$s भाषाको अनुवादलाई अघिल्लो बिल्डमा फर्काउने?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'दर्ता चुनौती अपेक्षित रूपमा छैन।','That is not a valid build identifier.'=>'त्यो मान्य बिल्ड पहिचानकर्ता होइन।','Refusing to write outside the Babilim language-file directory.'=>'Babilim भाषा-फाइल डाइरेक्टरी बाहिर लेख्न अस्वीकार गरियो।','Could not write the downloaded package to disk.'=>'डाउनलोड गरिएको प्याकेज डिस्कमा लेख्न सकिएन।','Unexpected HTTP %d response.'=>'अप्रत्याशित HTTP %d प्रतिक्रिया।','This site\'s URL, so the service can verify you own it.'=>'यो साइटको URL, ताकि सेवाले तपाईं यसको मालिक हुनुहुन्छ भनी प्रमाणित गर्न सकोस्।','Your WordPress version, to serve compatible translation files.'=>'तपाईंको WordPress संस्करण, ताकि उपयुक्त अनुवाद फाइलहरू उपलब्ध गराउन सकियोस्।','Your PHP version, for compatibility.'=>'तपाईंको PHP संस्करण, अनुकूलताका लागि।','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'यस प्लगइनको आफ्नै संस्करण, ताकि यो सेवासँग सञ्चार गर्न धेरै पुरानो भएमा सेवाले तपाईंलाई अपडेट गर्न भन्न सकोस्।','This site\'s configured locale.'=>'यो साइटको कन्फिगर गरिएको लोकेल।','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'यो साइटमा प्रयोगमा रहेका सबै लोकेलहरू (साइट लोकेल, स्थापना गरिएका भाषा प्याकहरू, प्रयोगकर्ता लोकेलहरू, र तपाईंले म्यानुअल रूपमा थपेका कुनै पनि)। कुनै पनि लोकेललाई अरूभन्दा फरक व्यवहार गरिँदैन।','(a public key generated for this site)'=>'(यस साइटका लागि उत्पन्न गरिएको सार्वजनिक कुञ्जी)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'यस साइटको स्थापना सार्वजनिक कुञ्जी, अनुरोधहरू साँच्चै यही साइटबाट आएका हुन् भनी प्रमाणित गर्न प्रयोग गरिन्छ। केवल सार्वजनिक भाग मात्र पठाइन्छ।','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'स्थापना गरिएका प्रत्येक प्लगइन/थिम: यसको स्लग, संस्करण, text domain(हरू), यो wp.org मा सूचीकृत छ कि छैन, यसका आफ्नै समावेश गरिएका लोकेलहरू, र कुन लोकेलहरूका लागि तपाईंले पहिल्यै Babilim अनुवाद स्थापना गरिसक्नुभएको छ।','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'WordPress.org मा नरहेको प्लगइन वा थिमको अपलोड तपाईंले पुष्टि गर्दा मात्र: त्यो कम्पोनेन्टको सम्पूर्ण डाइरेक्टरी, zip को रूपमा।','(generic codes and coordinates only)'=>'(सामान्य कोड र निर्देशाङ्क मात्र)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'बढीमा २० विचाराधीन निदानात्मक घटनाहरू (जस्तै अखण्डता जाँचमा असफल भएको फाइल), प्रत्येकमा केवल कोड, कम्पोनेन्ट र लोकेल हुन्छ, र कुनै पनि स्ट्रिङ सामग्री वा अनुवादित पाठ कहिल्यै हुँदैन।','Unsafe locale: %s'=>'असुरक्षित लोकेल: %s','Manifest unavailable: %s'=>'म्यानिफेस्ट उपलब्ध छैन: %s','Could not determine active components; the existing merged index was left unchanged.'=>'सक्रिय कम्पोनेन्टहरू निर्धारण गर्न सकिएन; विद्यमान मर्ज गरिएको सूची परिवर्तन नगरी छोडियो।','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'स्थापना गरिएका प्लगइन/थिमहरू निर्धारण गर्न सकिएन; सफाइ स्क्यान छोडियो, केही पनि मेटाइएन।','Sweep aborted without orphaning anything: %s.'=>'सफाइ स्क्यान केही पनि अनाथ नबनाई रोकियो: %s।','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'सफाइ सञ्चालन भयो, तर यसका केही परिवर्तनहरू अनुवाद सूचीमा अभिलेख गर्न सकिएन; अर्को सफाइले तिनलाई फेरि प्रयास गर्नेछ।','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' का लागि मर्ज गरिएको सूची पुनःनिर्माण गरियो, तर अनुवाद सूचीले यसलाई अभिलेख गर्न सकेन; अर्को पुनःनिर्माणले फेरि प्रयास गर्नेछ।','Could not write the staged merged index.'=>'स्टेज गरिएको मर्ज गरिएको सूची लेख्न सकिएन।','Re-parsed entry count did not match the built index.'=>'पुनः पार्स गरिएको प्रविष्टि सङ्ख्या निर्माण गरिएको सूचीसँग मेल खाएन।','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' का लागि मर्ज गरिएको सूची यथास्थानमा सार्न सकिएन; अघिल्लो प्रयोगमा रहेको सूची (यदि थियो भने) आधा-अपडेट अवस्थामा छोड्नुको सट्टा हटाइयो। अर्को सफल पुनःनिर्माणसम्म यस लोकेलका लागि कुनै पनि default-domain पूरक सेवा गरिने छैन।','Could not open zip: %s'=>'zip खोल्न सकिएन: %s','Zip has no manifest.json.'=>'Zip मा manifest.json छैन।','manifest.json in the zip is not valid JSON.'=>'zip भित्रको manifest.json मान्य JSON होइन।','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json को \'%s\' अपेक्षित मानसँग मेल खाँदैन।','Another installation is running; try again in a moment.'=>'अर्को स्थापना चलिरहेको छ; केही क्षणपछि फेरि प्रयास गर्नुहोस्।','Not a valid server_build_id: %s'=>'मान्य server_build_id होइन: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'प्याकेज म्यानिफेस्टको kind \'%1$s\' अनुरोध गरिएको kind \'%2$s\' सँग मेल खाँदैन।','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'प्याकेजको text domain \'%1$s\' यस साइटमा रहेको कम्पोनेन्टको प्रतिलिपि (\'%2$s\') सँग मेल खाँदैन, त्यसैले यो स्थापना गरिएन।','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'दिइएको डोमेन \'%1$s\' प्याकेज म्यानिफेस्टको आफ्नै स्लग \'%2$s\' वा यसको text_domain \'%3$s\' कुनैसँग पनि मेल खाँदैन।','Unsafe slug: %s'=>'असुरक्षित स्लग: %s','Unsafe text_domain: %s'=>'असुरक्षित text_domain: %s','The package has no %s for its own text domain.'=>'प्याकेजमा यसको आफ्नै टेक्स्ट डोमेनका लागि %s छैन।','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json हराइरहेको छ वा यसमा अमान्य \'%s\' छ।','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json हराइरहेको छ वा यसमा अमान्य \'entries\' छ।','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json हराइरहेको छ वा यसमा अमान्य \'files\' छ।','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json हराइरहेको छ वा यसमा अमान्य \'extra_domains\' छ।','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json हराइरहेको छ वा यसमा अमान्य \'build_no\' छ।','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json को \'server_build_id\' मान्य बिल्ड आईडी होइन।','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json को \'contract\' मान्य संस्करण स्ट्रिङ होइन।','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json को \'status\' मान ठ्याक्कै \'published\' हुनुपर्छ।','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'म्यानिफेस्ट फाइल manifest.json को \'kind\' \'plugin\' वा \'theme\' मध्ये एउटा हुनुपर्छ।','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json मा अमान्य \'default_domain_entries\' छ।','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json मा अमान्य \'default_domain_files\' छ।','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest हराइरहेको छ वा यसमा अमान्य \'%s\' छ।','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest को \'server_build_id\' मान्य बिल्ड आईडी होइन।','No record for %s'=>'%s को कुनै रेकर्ड छैन','One or more served files no longer match the manifest.'=>'एक वा बढी प्रदान गरिएका फाइलहरू अब म्यानिफेस्टसँग मेल खाँदैनन्।','No previous build to roll back to.'=>'पूर्वस्थितिमा फर्काउन कुनै अघिल्लो बिल्ड छैन।','The change could not be recorded in the translation index; please try again.'=>'परिवर्तन अनुवाद सूचीमा रेकर्ड गर्न सकिएन; कृपया फेरि प्रयास गर्नुहोस्।','Unknown kind: %s'=>'अज्ञात प्रकार: %s','Unsafe domain: %s'=>'असुरक्षित डोमेन: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'टेक्स्ट डोमेन \'%1$s\' (%2$s) पहिले नै अर्को स्थापित कम्पोनेन्ट (%3$s) का लागि प्रदान गरिएको छ; केही पनि स्थापना गरिएन।','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'पूर्वस्थितिमा फर्काउँदा \'%1$s\' (%2$s) ओभरराइट हुनेछ, जुन अहिले अर्को स्थापित कम्पोनेन्ट (%3$s) का लागि प्रदान गरिएको छ; केही पनि परिवर्तन गरिएन।','Zip is missing expected file: %s'=>'जिपमा अपेक्षित फाइल हराइरहेको छ: %s','sha256 mismatch for %s'=>'%s का लागि sha256 मेल खाएन','The package declares no main translation file.'=>'प्याकेजले कुनै मुख्य अनुवाद फाइल घोषणा गरेको छैन।','Zip is missing expected default file: %s'=>'जिपमा अपेक्षित पूर्वनिर्धारित फाइल हराइरहेको छ: %s','sha256 mismatch for default/%s'=>'default/%s को लागि sha256 मेल खाएन','Could not stage %s'=>'%s स्टेज गर्न सकिएन','Could not stage default/%s'=>'default/%s स्टेज गर्न सकिएन','Entry count mismatch for %s'=>'%s का लागि प्रविष्टि संख्या मेल खाएन','Could not verify entry count for %s'=>'%s का लागि प्रविष्टि संख्या प्रमाणित गर्न सकिएन','l10n.php entry count mismatch for %s'=>'%s का लागि l10n.php प्रविष्टि संख्या मेल खाएन','Default supplement entry count mismatch.'=>'पूर्वनिर्धारित पूरक प्रविष्टि संख्या मेल खाएन।','The package produced no servable main translation file.'=>'प्याकेजले प्रदान गर्न मिल्ने कुनै मुख्य अनुवाद फाइल उत्पादन गरेन।','Could not prepare %s for rollback.'=>'%s लाई पूर्वस्थितिमा फर्काउनका लागि तयार गर्न सकिएन।','Could not back up %s before replacing it.'=>'%s प्रतिस्थापन गर्नुअघि ब्याकअप गर्न सकिएन।','Could not move %s into place.'=>'%s लाई यथास्थानमा सार्न सकिएन।','English (United States)'=>'अंग्रेजी (संयुक्त राज्य अमेरिका)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest उपलब्ध छैन: %s','could not read _manifest.json: %s'=>'_manifest.json पढ्न सकिएन: %s','failed to parse _manifest.json: %s'=>'_manifest.json पार्स गर्न असफल भयो: %s','_manifest.json has an unexpected structure'=>'_manifest.json को संरचना अप्रत्याशित छ','Could not create the package archive.'=>'प्याकेज अभिलेख सिर्जना गर्न सकिएन।','No writable temporary directory is available for packaging.'=>'प्याकेजिङका लागि लेख्न मिल्ने कुनै अस्थायी डाइरेक्टरी उपलब्ध छैन।','A file in the component could not be read, so it was not packaged.'=>'कम्पोनेन्टमा रहेको एउटा फाइल पढ्न सकिएन, त्यसैले यसलाई प्याकेज गरिएन।','Only plugins and themes can be packaged.'=>'प्लगइन र थिमहरू मात्र प्याकेज गर्न सकिन्छ।','The component\'s main file was not found.'=>'कम्पोनेन्टको मुख्य फाइल फेला परेन।','The component is not inside the plugins or themes directory.'=>'कम्पोनेन्ट प्लगइन वा थिम डाइरेक्टरीभित्र छैन।','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim को यो चरणका लागि समय सकियो र यसले अर्को जाँचमा जारी राख्नेछ।','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim ले यो साइट प्रमाणित गर्न सकेन, त्यसैले प्रमाणीकरण सफल नभएसम्म केही पनि डाउनलोड वा इन्स्टल गरिने छैन।','Registration response was missing required fields.'=>'दर्ता प्रतिक्रियामा आवश्यक फिल्डहरू छुटेका थिए।','No pending challenge to verify.'=>'प्रमाणित गर्नका लागि कुनै विचाराधीन च्यालेन्ज छैन।','Verify response was missing site_token.'=>'प्रमाणीकरण प्रतिक्रियामा site_token छुटेको थियो।','No site id is on file to rotate a token for.'=>'टोकन परिवर्तन गर्नका लागि फाइलमा कुनै साइट आईडी छैन।','Rotate-token response was missing site_token.'=>'टोकन परिवर्तन प्रतिक्रियामा site_token छुटेको थियो।','nonce must be a hexadecimal string.'=>'nonce हेक्साडेसिमल स्ट्रिङ हुनुपर्छ।','No pending challenge for this nonce.'=>'यो nonce का लागि कुनै विचाराधीन च्यालेन्ज छैन।','Too many requests.'=>'धेरै अनुरोधहरू।','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'यो साइटमा %2$d भाषाहरूमा %1$d कम्पोनेन्टहरू छन्, जसका लागि %3$d जाँच ब्याचहरू आवश्यक पर्छ; Babilim ले प्रति रन बढीमा %4$d सम्हाल्न सक्छ। सेटिङहरूमा व्यवस्थापन गरिएका भाषाहरू घटाउनुहोस् वा प्रयोग नगरिएका प्लगइन र थिमहरू निष्क्रिय गर्नुहोस्, त्यसपछि अहिले फेरि जाँच गर्नुहोस् थिच्नुहोस्।','Babilim could not finish checking this site.'=>'Babilim ले यो साइटको जाँच पूरा गर्न सकेन।','This site\'s address is too long for Babilim to register.'=>'यो साइटको ठेगाना Babilim मा दर्ता गर्न धेरै लामो छ।','This site\'s locale code is not one Babilim can register.'=>'यो साइटको locale कोड Babilim ले दर्ता गर्न सक्ने कोड होइन।','The download response was missing a usable location.'=>'डाउनलोड प्रतिक्रियामा प्रयोग गर्न मिल्ने स्थान छुटेको थियो।','The service\'s upload offer was incomplete.'=>'सेवाको अपलोड प्रस्ताव अपूर्ण थियो।','This component is larger than the service accepts, so it cannot be uploaded.'=>'यो कम्पोनेन्ट सेवाले स्वीकार गर्ने भन्दा ठूलो छ, त्यसैले अपलोड गर्न सकिँदैन।','The packaged component could not be read.'=>'प्याकेज गरिएको कम्पोनेन्ट पढ्न सकिएन।','A part of the upload kept failing, so the upload was cancelled.'=>'अपलोडको एउटा भाग बारम्बार असफल भयो, त्यसैले अपलोड रद्द गरियो।','Could not read: %s'=>'पढ्न सकिएन: %s']];